'use client'
import React, { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { DecisionPhaseProps, ResultType } from '@/lib/types'
import { playMenuHover, playMenuSelect } from '@/lib/sounds'

export default function DecisionPhase({ question = 1, onResult, sounds }: DecisionPhaseProps) {
    const qRef = useRef<HTMLDivElement | null>(null)
    const buttonsRef = useRef<(HTMLButtonElement | null)[]>([])

    useEffect(() => {
        try {
            if (sounds?.ambience) {
                sounds.ambience.fade(0.35, 0, 600)
                setTimeout(() => {
                    try {
                        sounds.ambience?.stop()
                    } catch (_) {}
                }, 650)
            }
        } catch (e) {
            console.warn('Audio notice in decision phase:', e)
        }

        if (qRef.current) {
            gsap.fromTo(
                qRef.current,
                { scale: 0.94, opacity: 0, y: 15 },
                { scale: 1, opacity: 1, y: 0, duration: 0.5, ease: 'power3.out' }
            )
        }

        return () => {
            if (qRef.current) gsap.killTweensOf(qRef.current)
            buttonsRef.current.forEach((btn) => {
                if (btn) gsap.killTweensOf(btn)
            })
        }
    }, [sounds])

    const handleAnswer = (answer: 'yes' | 'no', e: React.MouseEvent<HTMLButtonElement>) => {
        const btn = e.currentTarget
        playMenuSelect()

        gsap.to(btn, {
            backgroundColor: '#ffffff',
            color: '#000000',
            scale: 1.06,
            duration: 0.1,
            yoyo: true,
            repeat: 1,
            ease: 'power2.out',
            onComplete: () => {
                try {
                    if (typeof window !== 'undefined' && window.localStorage) {
                        if (question === 1) {
                            localStorage.setItem('programmerAnswer', answer)
                        } else {
                            localStorage.setItem('profileInterest', answer)
                        }
                    }
                } catch (err) {
                    console.warn('LocalStorage notice:', err)
                }

                if (question === 1) {
                    const res: ResultType = answer === 'yes' ? 'passed-access' : 'failed-denied'
                    onResult(res)
                } else {
                    const res: ResultType = answer === 'yes' ? 'passed-portfolio' : 'failed-redirect'
                    onResult(res)
                }
            },
        })
    }

    const isQ1 = question === 1

    return (
        <div
            style={{
                position: 'fixed',
                inset: 0,
                background: 'radial-gradient(ellipse at center, #0e0e14 0%, #050507 100%)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 100,
                userSelect: 'none',
                padding: '20px',
            }}
        >
            <div className="heavy-vignette" />

            <div
                ref={qRef}
                style={{
                    background: 'rgba(12, 12, 16, 0.92)',
                    backdropFilter: 'blur(20px)',
                    WebkitBackdropFilter: 'blur(20px)',
                    border: '1px solid rgba(255, 255, 255, 0.18)',
                    borderTop: '3px solid #f5a623',
                    padding: '48px 60px',
                    textAlign: 'center',
                    maxWidth: '640px',
                    width: '92%',
                    boxShadow: '0 25px 70px rgba(0, 0, 0, 0.95), 0 0 30px rgba(245, 166, 35, 0.15)',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    zIndex: 110,
                }}
            >
                <p
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.35em',
                        color: '#f5a623',
                        textTransform: 'uppercase',
                        marginBottom: '20px',
                        fontWeight: 700,
                    }}
                >
                    MISSION PROTOCOL // QUESTION 0{question} OF 02
                </p>

                <h2
                    style={{
                        fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                        fontSize: 'clamp(2rem, 4.8vw, 2.9rem)',
                        letterSpacing: '0.04em',
                        textTransform: 'uppercase',
                        color: '#ffffff',
                        marginBottom: '44px',
                        lineHeight: 1.08,
                        textShadow: '0 4px 15px rgba(0, 0, 0, 0.8)',
                    }}
                >
                    {isQ1 ? (
                        <>
                            ARE YOU A<br />
                            DEVELOPER?
                        </>
                    ) : (
                        <>
                            WOULD YOU LIKE TO<br />
                            EXPLORE MY PORTFOLIO?
                        </>
                    )}
                </h2>

                <div style={{ display: 'flex', gap: '32px', justifyContent: 'center' }}>
                    <button
                        ref={(el) => {
                            buttonsRef.current[0] = el
                        }}
                        className="decision-btn"
                        onClick={(e) => handleAnswer('yes', e)}
                        onMouseEnter={(e: React.MouseEvent<HTMLButtonElement>) => {
                            playMenuHover()
                            e.currentTarget.style.background = '#ffffff'
                            e.currentTarget.style.color = '#000000'
                            e.currentTarget.style.borderColor = '#ffffff'
                            e.currentTarget.style.boxShadow = '0 0 25px rgba(255, 255, 255, 0.8)'
                        }}
                        style={{
                            fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                            background: 'rgba(255, 255, 255, 0.05)',
                            border: '2px solid rgba(255, 255, 255, 0.3)',
                            color: '#ffffff',
                            fontSize: 'clamp(1.3rem, 2.8vw, 1.7rem)',
                            letterSpacing: '0.15em',
                            cursor: 'pointer',
                            padding: '10px 36px',
                            outline: 'none',
                            transition: 'all 0.18s ease',
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.background = 'rgba(255, 255, 255, 0.05)'
                            e.currentTarget.style.color = '#ffffff'
                            e.currentTarget.style.borderColor = 'rgba(255, 255, 255, 0.3)'
                            e.currentTarget.style.boxShadow = 'none'
                        }}
                    >
                        [ YES ]
                    </button>
                    <button
                        ref={(el) => {
                            buttonsRef.current[1] = el
                        }}
                        className="decision-btn"
                        onClick={(e) => handleAnswer('no', e)}
                        onMouseEnter={(e: React.MouseEvent<HTMLButtonElement>) => {
                            playMenuHover()
                            e.currentTarget.style.background = '#ffffff'
                            e.currentTarget.style.color = '#000000'
                            e.currentTarget.style.borderColor = '#ffffff'
                            e.currentTarget.style.boxShadow = '0 0 25px rgba(255, 255, 255, 0.8)'
                        }}
                        style={{
                            fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                            background: 'rgba(255, 255, 255, 0.05)',
                            border: '2px solid rgba(255, 255, 255, 0.3)',
                            color: '#ffffff',
                            fontSize: 'clamp(1.3rem, 2.8vw, 1.7rem)',
                            letterSpacing: '0.15em',
                            cursor: 'pointer',
                            padding: '10px 36px',
                            outline: 'none',
                            transition: 'all 0.18s ease',
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.background = 'rgba(255, 255, 255, 0.05)'
                            e.currentTarget.style.color = '#ffffff'
                            e.currentTarget.style.borderColor = 'rgba(255, 255, 255, 0.3)'
                            e.currentTarget.style.boxShadow = 'none'
                        }}
                    >
                        [ NO ]
                    </button>
                </div>
            </div>
        </div>
    )
}
